// Authentication can retain only the notification destinations generated by
// SimplSEO. Never trust a return URL supplied by an email or browser.
export function safeNotificationReturn(value) {
  if (value === '/settings?tab=notifications') return value;
  if (typeof value !== 'string' || !/^\/notifications(?:\/[A-Za-z0-9_-]{1,160})?$/.test(value)) return null;
  if (value === '/notifications/unsubscribe') return null;
  return value;
}

export function notificationReturnFromLocation(location) {
  if (!location) return null;
  const direct = safeNotificationReturn(`${location.pathname}${location.search || ''}`);
  if (direct) return direct;
  return safeNotificationReturn(new URLSearchParams(location.search || '').get('returnTo'));
}

export function notificationAuthPath(path, destination) {
  const safe = safeNotificationReturn(destination);
  return safe ? `${path}?returnTo=${encodeURIComponent(safe)}` : path;
}

export function safeNotificationDestination(value) {
  if (typeof value !== 'string' || !value.startsWith('/') || value.startsWith('//') || /[\\\u0000-\u0020]/.test(value)) return null;
  try {
    const url = new URL(value, 'https://simplseo.invalid');
    if (url.origin !== 'https://simplseo.invalid' || !['/low-ctr', '/generic-keywords', '/settings', '/dashboard'].includes(url.pathname)) return null;
    return `${url.pathname}${url.search}${url.hash}`;
  } catch { return null; }
}
